python3 -c "
import json

paths = {
    'probe_001 (SFR)': '/root/autodl-tmp/agent_progress_probe/checkpoints/split_info.json',
    'e5-large': '/root/autodl-tmp/agent_progress_probe/checkpoints_ablation_e5large/split_info.json',
    'bge-m3': '/root/autodl-tmp/agent_progress_probe/checkpoints_ablation_bgem3/split_info.json',
}

splits = {}
for name, path in paths.items():
    try:
        with open(path) as f:
            si = json.load(f)
        splits[name] = si
        print(f'{name}: keys={list(si.keys())}')
        for k, v in si.items():
            if isinstance(v, list):
                print(f'  {k}: list[{len(v)}], first3={v[:3]}, last3={v[-3:]}')
            elif isinstance(v, dict):
                print(f'  {k}: dict with {len(v)} keys')
            elif isinstance(v, (int, float, str)):
                print(f'  {k}: {v}')
    except Exception as e:
        print(f'{name}: ERROR - {e}')

print()
print('=== COMPARISON ===')
names = list(splits.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        n1, n2 = names[i], names[j]
        s1, s2 = splits[n1], splits[n2]
        for key in ['test_indices', 'test_instance_ids', 'test_instances']:
            if key in s1 and key in s2:
                t1, t2 = s1[key], s2[key]
                set1, set2 = set(map(str, t1)), set(map(str, t2))
                order_match = t1 == t2
                set_match = set1 == set2
                print(f'{n1} vs {n2} ({key}): len={len(t1)} vs {len(t2)}, set_match={set_match}, order_match={order_match}')
                if not set_match:
                    print(f'  only_in_{n1}: {len(set1 - set2)}')
                    print(f'  only_in_{n2}: {len(set2 - set1)}')
        if 'random_seed' in s1 and 'random_seed' in s2:
            print(f'{n1} vs {n2} (random_seed): {s1[\"random_seed\"]} vs {s2[\"random_seed\"]}, match={s1[\"random_seed\"]==s2[\"random_seed\"]}')
"
